  "insurance": ["469"], "sığorta": ["469"],
  "emergency": ["331"], "təcili": ["331"],
  "test": ["343"], "müayinə": ["343"], "imtina": ["343"],
  "exhaust": ["342"], "səs": ["342"], "phone": ["342"], "telefon": ["342"],
  "racing": ["511"], "yarış": ["511"], "drift": ["511"], "wheelie": ["511"], "xuliqan": ["511"], "burnout": ["511"],
  "bicycle": ["338", "327"], "velosiped": ["338", "327"], "scooter": ["338"], "skuter": ["338"],
  "railway": ["327"], "dəmiryol": ["327"],
  "one-way": ["327"], "birtərəfli": ["327"],
  "registration": ["339"], "qeydiyyat": ["339"], "texniki": ["339"],
  "plate": ["342"], "nömrə": ["342"],
  "first aid": ["356"], "dərman": ["356"]
};

const matched = new Set();
for (const [k, ids] of Object.entries(kw)) {
  if (q.includes(k)) ids.forEach(id => matched.add(id));
}

// Check for article numbers mentioned directly
const articleMatch = q.match(/(?:maddə|article|mad\.?)\s*(\d{3}(?:-\d)?)/gi);
if (articleMatch) {
  articleMatch.forEach(m => {
    const num = m.match(/(\d{3}(?:-\d)?)/)[1];
    matched.add(num);
  });
}

// Fallback search
if (matched.size === 0) {
  for (const a of knowledgeBase.articles) {
    const words = q.split(/\s+/).filter(w => w.length > 3);
    if (words.some(w => JSON.stringify(a).toLowerCase().includes(w))) {
      matched.add(a.id);
    }
  }
}

const results = knowledgeBase.articles.filter(a => matched.has(a.id)).slice(0, 4);
if (results.length === 0) {
  results.push(knowledgeBase.articles[0], knowledgeBase.articles[1], knowledgeBase.articles[2]);
}

let ctx = "AZƏRBAYCAN YOL CƏRİMƏLƏRİ (Rəsmi Məlumat - Cərimə və Ballar Cədvəli):\n";
for (const a of results) {
  ctx += `\nMaddə ${a.id} - ${a.title} (${a.titleEn}):\n`;
  for (const i of a.content) {
    const fine = typeof i.f === 'number' ? `${i.f} AZN` : i.f;
    ctx += `  ${i.sub}: ${i.v} - ${fine}${i.p ? `, ${i.p} bal/points` : ""}\n`;
  }
}

