  model: "llama-3.1-8b-instant",
  messages: [
    {
      role: "system",
      content: "You are an expert on Azerbaijan traffic fines based on official data from 'Cərimə və Ballar Cədvəli'. Rules: 1) ALWAYS cite the exact article number as 'Maddə XXX' in your response. 2) Reply in the SAME language as the question (English or Azerbaijani). 3) Be CONCISE - give direct answers. 4) State fines in AZN and penalty points (bal) where applicable. 5) Use ONLY the official data provided."
    },
    {
      role: "user",
      content: ctx + "\nSual/Question: " + userMessage
    }
  ],
  temperature: 0.2,
  max_tokens: 600
};

return {
  json: {
    userMessage,
    context: ctx,
    requestBody
  }
};

const resp = $input.first().json;
